-- Phase 7: persisted image-generation jobs.
--
-- One row per explicit generation request. It records the prompt, provider,
-- model key, settings, the provider's job id, the cost estimate and rate
-- version used, and the media row created from the generated bytes. Provider
-- credentials and API keys are never stored here.
--
-- The table is server-only: every route proves Supabase ownership first and
-- talks to this table with the service role. No policy grants anon or
-- authenticated access.

create table if not exists public.image_generations (
  id uuid primary key,
  owner_id uuid not null references auth.users(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,
  provider text not null check (provider in ('cloudflare', 'leonardo')),
  model_key text not null,
  prompt text not null check (char_length(prompt) between 1 and 2048),
  -- Width, height, steps, and any other request settings exactly as sent.
  settings jsonb not null check (jsonb_typeof(settings) = 'object'),
  status text not null default 'pending' check (status in ('pending', 'succeeded', 'failed')),
  -- Cloudflare generates synchronously; Leonardo returns an async job id.
  job_id text,
  media_id uuid references public.media_metadata(id) on delete set null,
  estimated_usd numeric(12, 6),
  estimated_neurons numeric(10, 2),
  rate_version text not null,
  -- Provider-reported cost, when it supplies one (e.g. API credit).
  provider_cost jsonb,
  error_code text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists image_generations_project_idx
  on public.image_generations (owner_id, project_id, created_at desc);

do $$
begin
  alter table public.image_generations enable row level security;
  revoke all on public.image_generations from anon, authenticated;
  grant select, insert, update, delete on public.image_generations to service_role;
end $$;
